'use strict';
(() => {
const E=window.VerizonModel,V=window.VerizonView,$=id=>document.getElementById(id),model=new E.Model(),view=new V.View($('facility'));
let running=!matchMedia('(prefers-reduced-motion: reduce)').matches,speed=1,selection='YC-01',follow=false,tour=false,tourAt=0,tourIndex=0,last=null,paintAt=0;
const cameras=[...document.querySelectorAll('[data-view]')],holds=[...document.querySelectorAll('[data-hold]')];
const option=(value,name)=>{const o=document.createElement('option');o.value=value;o.textContent=name;return o;};
for(const [name,items]of [['Yaskawa cobots',model.arms],['AMR fleet · visual allocation',model.bots],['Process areas',E.stages]]){const group=document.createElement('optgroup');group.label=name;items.forEach(x=>group.append(option(x.id,x.name||x.id)));$('selection').append(group);}const currentDevice=option('DEMO-000','Selected device');$('selection').append(currentDevice);
function selected(){return model.arms.find(x=>x.id===selection)||model.bots.find(x=>x.id===selection)||model.units.find(x=>x.id===selection)||E.nodes[selection];}
function setCamera(key,changeURL=true){if(!Object.hasOwn(V.presets,key))key='site';view.fit(key);$('view-name').textContent=V.presets[key].label;cameras.forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.view===key)));follow=false;$('follow').setAttribute('aria-pressed','false');if(changeURL)history.replaceState(null,'','#'+key);view.draw(model);}
function select(id,locate=false){if(!model.arms.some(x=>x.id===id)&&!model.bots.some(x=>x.id===id)&&!model.units.some(x=>x.id===id)&&!E.nodes[id])return;selection=id;view.selected=id;if(id.startsWith('DEMO-')){currentDevice.value=id;currentDevice.textContent=id+' · '+model.units.find(x=>x.id===id).brand;}$('selection').value=id;follow=false;$('follow').setAttribute('aria-pressed','false');if(locate)locateSelected();update();}
function locateSelected(){const s=selected();if(!s)return;view.focusAt(s.x+(s.w||0)/2,s.y+(s.h||0)/2,s.w?Math.max(350,s.w*2):390);$('view-name').textContent=s.name||s.id;cameras.forEach(b=>b.setAttribute('aria-pressed','false'));view.draw(model);}
function update(){let s=selected();if(!s&&selection.startsWith('DEMO-')){$('agent-name').textContent=selection;$('agent-state').textContent='Dispatched';$('agent-description').textContent='This demonstration device completed its example route. Select another device to continue.';$('route-trace').textContent='';follow=false;}else if(s){$('agent-name').textContent=s.name||s.id;$('agent-state').textContent=s.state||(model.held(s.id)?'Hold':'Process area');$('agent-description').textContent=s.note||(s.id.startsWith('YC')?'Representative Yaskawa approach → pick → transfer → place cycle. Placement and cell assignment are schematic.':s.id.startsWith('AMR')?'AMR carrier moving through a representative aisle loop. The reverse / forward fleet split is illustrative.':s.brand+' device on the '+model.profile+' example route.');$('route-trace').textContent=s.route?s.route.map((id,i)=>(i===s.index?'● ':'')+E.nodes[id].name).join(' → '):'';V.closeup($('closeup').getContext('2d'),selection,model);}
 const summary=model.summary();for(const key of ['moving','processing','waiting'])$(key).textContent=summary[key];holds.forEach(b=>b.setAttribute('aria-pressed',String(model.flags[b.dataset.hold])));const active=Object.keys(model.flags).filter(k=>model.flags[k]);$('scene-status').textContent=active.length?'Active holds: '+active.join(' · '):'Illustrative motion · all paths open';$('scene-status').classList.toggle('held',!!active.length);$('play').textContent=running?'Pause':'Play';$('event-list').replaceChildren(...model.events.map(e=>{const li=document.createElement('li');li.textContent=e.text;return li;}));}
function resize(){const r=$('viewport').getBoundingClientRect(),key=view.focus;view.resize(r.width,r.height,window.devicePixelRatio||1);if(Object.hasOwn(V.presets,key))view.fit(key);else if(!key)view.fit('site');view.draw(model);}
$('play').addEventListener('click',()=>{running=!running;last=null;update();});$('speed').addEventListener('change',e=>speed=Number(e.target.value));$('reset').addEventListener('click',()=>{model.reset();select('YC-01');update();view.draw(model);});
$('profile').addEventListener('change',e=>{model.setProfile(e.target.value);select('YC-01');update();view.draw(model);});$('brand').addEventListener('change',e=>{model.setBrand(e.target.value);select('YC-01');update();view.draw(model);});$('selection').addEventListener('change',e=>select(e.target.value));$('locate').addEventListener('click',locateSelected);$('follow').addEventListener('click',()=>{const s=selected();if(!s)return;follow=!follow;$('follow').setAttribute('aria-pressed',String(follow));if(follow)locateSelected();});$('device').addEventListener('click',()=>{const network=view.focus==='forward'?'forward':'reverse',u=model.units.find(x=>x.network===network)||model.units[0];if(u){select(u.id,true);follow=true;$('follow').setAttribute('aria-pressed','true');}});
$('clear').addEventListener('click',()=>{model.clear();update();view.draw(model);});holds.forEach(b=>b.addEventListener('click',()=>{model.toggle(b.dataset.hold);update();view.draw(model);}));cameras.forEach(b=>b.addEventListener('click',()=>setCamera(b.dataset.view)));$('fit').addEventListener('click',()=>setCamera('site'));$('paths').addEventListener('click',()=>{view.paths=!view.paths;$('paths').setAttribute('aria-pressed',String(view.paths));view.draw(model);});$('depth').addEventListener('click',()=>{view.depth=!view.depth;$('depth').setAttribute('aria-pressed',String(view.depth));view.draw(model);});$('tour').addEventListener('click',()=>{tour=!tour;tourAt=model.t;tourIndex=0;$('tour').setAttribute('aria-pressed',String(tour));if(tour){running=true;setCamera('reverse');update();}});
function stopFollow(){follow=false;$('follow').setAttribute('aria-pressed','false');tour=false;$('tour').setAttribute('aria-pressed','false');}
$('zoom-in').addEventListener('click',()=>{stopFollow();view.zoom(1.25);view.draw(model);});$('zoom-out').addEventListener('click',()=>{stopFollow();view.zoom(.8);view.draw(model);});
const canvas=$('facility');let drag=null;
canvas.addEventListener('pointerdown',e=>{stopFollow();drag={x:e.clientX,y:e.clientY,startX:e.clientX,startY:e.clientY};canvas.setPointerCapture(e.pointerId);canvas.classList.add('dragging');});
canvas.addEventListener('pointermove',e=>{if(!drag)return;view.camera.x-=(e.clientX-drag.x)/view.camera.scale;view.camera.y-=(e.clientY-drag.y)/view.camera.scale;drag.x=e.clientX;drag.y=e.clientY;view.draw(model);});
canvas.addEventListener('pointerup',e=>{if(!drag)return;if(Math.hypot(e.clientX-drag.startX,e.clientY-drag.startY)<5){const r=canvas.getBoundingClientRect(),id=view.selectAt(e.clientX-r.left,e.clientY-r.top);if(id)select(id);}drag=null;canvas.classList.remove('dragging');});canvas.addEventListener('pointercancel',()=>{drag=null;canvas.classList.remove('dragging');});
canvas.addEventListener('wheel',e=>{e.preventDefault();stopFollow();const r=canvas.getBoundingClientRect();view.zoom(e.deltaY<0?1.12:.89,e.clientX-r.left,e.clientY-r.top);view.draw(model);},{passive:false});
canvas.addEventListener('keydown',e=>{if(!['ArrowLeft','ArrowRight','ArrowUp','ArrowDown','+','=','-','Home',' '].includes(e.key))return;e.preventDefault();stopFollow();const delta=45/view.camera.scale;if(e.key==='ArrowLeft')view.camera.x-=delta;if(e.key==='ArrowRight')view.camera.x+=delta;if(e.key==='ArrowUp')view.camera.y-=delta;if(e.key==='ArrowDown')view.camera.y+=delta;if(['+','='].includes(e.key))view.zoom(1.2);if(e.key==='-')view.zoom(.8);if(e.key==='Home')setCamera('site');if(e.key===' '){running=!running;update();}view.draw(model);});
$('notes').addEventListener('click',()=>$('model-notes').showModal());$('close-notes').addEventListener('click',()=>$('model-notes').close());$('model-notes').addEventListener('click',e=>{if(e.target===$('model-notes'))$('model-notes').close();});
let embeddedVisible=true;
window.addEventListener?.('message',event=>{if(window.parent!==window&&event.source===window.parent&&event.data?.type==='portfolio:visibility')embeddedVisible=event.data.visible===true;});
window.addEventListener?.('hashchange',()=>{const key=location.hash.slice(1);setCamera(key,false);if(key==='forward')select('f-asrs');else if(key==='reverse')select('YC-01');});
function loop(now){const dt=last===null?0:Math.min((now-last)/1000,.1);last=now;if(embeddedVisible&&!document.hidden){if(running)model.step(dt*speed);if(tour&&model.t-tourAt>8){const keys=['reverse','grading','function','rf','pack','forward','site'];tourIndex=(tourIndex+1)%keys.length;setCamera(keys[tourIndex]);tourAt=model.t;}if(follow){const s=selected();if(s){view.camera.x=s.x+(s.w||0)/2;view.camera.y=s.y+(s.h||0)/2;}}view.draw(model);if(now-paintAt>120){update();paintAt=now;}}requestAnimationFrame(loop);}
new ResizeObserver(resize).observe($('viewport'));resize();setCamera(location.hash.slice(1)||'site',false);select(location.hash==='#forward'?'f-asrs':'YC-01');update();requestAnimationFrame(loop);window.VerizonFlow={model,view,select,setCamera};
})();
